package com.primehr.rewardsrecognition.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="rr_decision_issue") public class RrDecisionIssue extends RspAuditedEntity{public enum Status{OPEN,RESOLVED,DISMISSED}@Column(name="evaluation_case_id",nullable=false,length=36)private String evaluationCaseId;@Column(nullable=false,length=4000)private String grounds;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="filed_by",nullable=false,length=100)private String filedBy;@Column(name="filed_at",nullable=false)private Instant filedAt;@Column(name="resolution_reason",length=4000)private String resolutionReason;@Column(name="resolved_by",length=100)private String resolvedBy;@Column(name="resolved_at")private Instant resolvedAt;protected RrDecisionIssue(){}public RrDecisionIssue(String a,String c,String grounds,String actor,Instant at){super(a);evaluationCaseId=requiredText(c,"evaluationCaseId");this.grounds=requiredText(grounds,"grounds");filedBy=requiredText(actor,"actor");filedAt=at;status=Status.OPEN;}public void resolve(String reason,String actor,Instant at,boolean dismissed){if(status!=Status.OPEN)throw new IllegalStateException("Issue is already resolved");resolutionReason=requiredText(reason,"reason");resolvedBy=requiredText(actor,"actor");resolvedAt=at;status=dismissed?Status.DISMISSED:Status.RESOLVED;}public String getEvaluationCaseId(){return evaluationCaseId;}public String getGrounds(){return grounds;}public Status getStatus(){return status;}public String getFiledBy(){return filedBy;}public Instant getFiledAt(){return filedAt;}public String getResolutionReason(){return resolutionReason;}public String getResolvedBy(){return resolvedBy;}public Instant getResolvedAt(){return resolvedAt;}}
